import {t} from './translations.js';
import {$,$$,el,readLocal,saveLocal,httpsURL,external,toast} from './shared.js';
let base=[],category='全部资源',onlyFavorite=false;
const storedFavorites=readLocal('atlas-favorites-v1',[]);let favorites=new Set(Array.isArray(storedFavorites)?storedFavorites.filter(id=>typeof id==='string'):[]);
const storedCustom=readLocal('atlas-custom-v1',[]);let custom=Array.isArray(storedCustom)?storedCustom.filter(r=>r&&typeof r.id==='string'&&typeof r.name==='string'&&typeof r.description==='string'&&typeof r.category==='string'&&httpsURL(r.url)).slice(0,100):[];
const categories=['全部资源','AI 工具','自动化','云开发','前端设计','社区学习'];
function renderFilters(){const nav=$('#resource-filters');nav.replaceChildren();for(const name of categories){const b=el('button',name,name===category?'active':'');b.setAttribute('aria-pressed',String(name===category));b.addEventListener('click',()=>{category=name;renderFilters();render();});nav.append(b);}}
function render(){const query=$('#resource-search').value.toLowerCase().trim();const items=[...base,...custom].filter(r=>(category==='全部资源'||r.category===category)&&(!onlyFavorite||favorites.has(r.id))&&`${r.name} ${r.description} ${r.category} ${t(r.description)} ${t(r.category)}`.toLowerCase().includes(query));$('#resource-count').textContent=`${items.length} 个匹配资源 · ${base.length} 个精选入口 / ${custom.length} 个自定义链接`;
 $('#resource-grid').replaceChildren();for(const r of items){const card=el('article',undefined,'resource-card'),top=el('div',undefined,'resource-top'),favorite=el('button',favorites.has(r.id)?'★':'☆','favorite'),bottom=el('div',undefined,'row');favorite.setAttribute('aria-label',(favorites.has(r.id)?'取消收藏 ':'收藏 ')+r.name);favorite.setAttribute('aria-pressed',String(favorites.has(r.id)));favorite.addEventListener('click',()=>{if(favorites.has(r.id))favorites.delete(r.id);else favorites.add(r.id);saveLocal('atlas-favorites-v1',[...favorites]);render();const same=[...document.querySelectorAll('.favorite')].find(n=>n.dataset.id===r.id);same?.focus();});favorite.dataset.id=r.id;top.append(el('span',r.name.slice(0,2).toUpperCase(),'resource-icon'),favorite);const link=external(r.url,'访问资源');link.className='link';bottom.append(el('span',r.label??r.category,'badge'),link);const titleNode=el('h3',r.name),descriptionNode=el('p',r.description);if(r.id.startsWith('custom-')){titleNode.dataset.noI18n='';descriptionNode.dataset.noI18n='';}card.append(top,titleNode,descriptionNode,bottom);if(r.id.startsWith('custom-')){const remove=el('button','移除自定义链接','small');remove.style.marginTop='16px';remove.addEventListener('click',()=>{if(confirm(t('移除这个自定义链接？'))){custom=custom.filter(c=>c.id!==r.id);favorites.delete(r.id);saveLocal('atlas-custom-v1',custom);saveLocal('atlas-favorites-v1',[...favorites]);render();}});card.append(remove);}$('#resource-grid').append(card);}
 if(!items.length)$('#resource-grid').append(el('p','没有匹配资源。试试其他分类，或添加自己的链接。','empty'));
}
$('#resource-search').addEventListener('input',render);
$('#favorite-filter').addEventListener('click',()=>{onlyFavorite=!onlyFavorite;$('#favorite-filter').setAttribute('aria-pressed',String(onlyFavorite));$('#favorite-filter').classList.toggle('primary',onlyFavorite);render();});
$('#add-resource').addEventListener('click',()=>{if(custom.length>=100){toast('最多保存 100 个自定义资源。');return;}$('#resource-form').reset();$('#resource-error').hidden=true;$('#resource-dialog').showModal();});
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('#resource-form').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target)),url=httpsURL(values.url);if(!url||!values.name.trim()||!values.description.trim()){$('#resource-error').textContent='请填写名称、简介和有效的 HTTPS 网址。';$('#resource-error').hidden=false;return;}custom.push({...values,url,name:values.name.trim(),description:values.description.trim(),id:'custom-'+crypto.randomUUID()});saveLocal('atlas-custom-v1',custom);category='全部资源';onlyFavorite=false;$('#resource-search').value='';$('#favorite-filter').classList.remove('primary');$('#favorite-filter').setAttribute('aria-pressed','false');renderFilters();render();$('#resource-dialog').close();toast('资源已保存到当前浏览器。');});
async function init(){try{const r=await fetch('data/resources.json');if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data)||data.some(item=>!httpsURL(item.url)))throw Error();base=data;renderFilters();render();}catch{$('#resource-count').textContent='精选资源加载失败，请刷新页面。';renderFilters();render();$('#resource-count').textContent='精选资源加载失败，当前仅显示本地自定义链接。';}}
document.addEventListener('languagechange',()=>{renderFilters();render();});
init();
